def _find_root(start: pathlib.Path) -> pathlib.Path:
    for cand in [start, *start.parents]:
        if (cand / "AGENTS.md").is_file() and (cand / "scratch").is_dir():
            return cand
    raise VerifyError("workspace root (AGENTS.md + scratch/) not found")


